var turalyon = context.rulePiece;
if (!turalyon || turalyon.currentHp <= 0 || context.playerId !== turalyon.ownerPlayerId) return { success: false, message: '' };
if (['holy-smite', 'holy-heal', 'holy-charge'].indexOf(context.cardId) === -1) return { success: false, message: '' };
var turnNumber = battle.turn && battle.turn.turnNumber ? battle.turn.turnNumber : 0;
if (!battle.extensions) battle.extensions = {}; if (!battle.extensions.turalyonLightforgedTurns) battle.extensions.turalyonLightforgedTurns = {};
var firedTurns = battle.extensions.turalyonLightforgedTurns;
if (context.cancelled) { firedTurns[turalyon.instanceId] = turnNumber; return { success: true, message: turalyon.name + '放弃了本回合的远征移动' }; }
var selectedTargets = Array.isArray(context.selectedTargets) ? context.selectedTargets : [];
if (selectedTargets.length === 0 && firedTurns[turalyon.instanceId] === turnNumber) return { success: false, message: '' };
function livingAt(x, y) { return battle.pieces.find(function(piece) { return piece.currentHp > 0 && piece.x === x && piece.y === y; }); }
function tileAt(x, y) { return battle.map.tiles.find(function(tile) { return tile.x === x && tile.y === y; }); }
function destinationsFor(mover) {
  var destinations = []; var maxDistance = (mover.moveRange || 0) + 2; var queue = [{ x: mover.x, y: mover.y, distance: 0 }]; var seen = {}; seen[mover.x + ',' + mover.y] = true;
  for (var qi = 0; qi < queue.length; qi++) { var current = queue[qi]; if (current.distance >= maxDistance) continue; var offsets = [[0, -1], [-1, 0], [1, 0], [0, 1]]; for (var oi = 0; oi < offsets.length; oi++) { var x = current.x + offsets[oi][0]; var y = current.y + offsets[oi][1]; var key = x + ',' + y; if (seen[key]) continue; seen[key] = true; var tile = tileAt(x, y); if (!tile || !tile.props || !tile.props.walkable) continue; var occupant = livingAt(x, y); if (occupant && occupant.ownerPlayerId !== mover.ownerPlayerId) continue; var nextDistance = current.distance + 1; queue.push({ x: x, y: y, distance: nextDistance }); if (!occupant) destinations.push({ type: 'cell', x: x, y: y }); } }
  return destinations;
}
var allies = battle.pieces.filter(function(piece) { return piece.currentHp > 0 && piece.ownerPlayerId === turalyon.ownerPlayerId && piece.x !== null && piece.y !== null; }).sort(function(a, b) { return a.instanceId < b.instanceId ? -1 : (a.instanceId > b.instanceId ? 1 : 0); });
if (selectedTargets.length === 0) {
  var moverCandidates = allies.filter(function(piece) { return destinationsFor(piece).length > 0; }).map(function(piece) { return { type: 'piece', pieceId: piece.instanceId }; });
  if (moverCandidates.length === 0) { firedTurns[turalyon.instanceId] = turnNumber; return { success: false, message: '' }; }
  return { success: false, needsTargetSelection: true, playerId: turalyon.ownerPlayerId, title: '圣铸进军：选择一名友方角色', targetType: 'piece', filter: 'ally', canCancel: true, resumeOnCancel: true, targetCandidates: moverCandidates };
}
var moverRef = selectedTargets[0];
var mover = moverRef && moverRef.type === 'piece' ? allies.find(function(piece) { return piece.instanceId === moverRef.pieceId; }) : null;
if (!mover) return { success: false, message: '选择的远征角色已失效' };
var destinations = destinationsFor(mover);
if (selectedTargets.length === 1) {
  return { success: false, needsTargetSelection: true, playerId: turalyon.ownerPlayerId, title: '圣铸进军：选择' + (mover.name || mover.templateId) + '的落点', targetType: 'grid', filter: 'all', canCancel: true, resumeOnCancel: true, targetCandidates: destinations };
}
var destinationRef = selectedTargets[1];
var destination = destinationRef && destinationRef.type === 'cell' ? destinations.find(function(cell) { return cell.x === destinationRef.x && cell.y === destinationRef.y; }) : null;
if (!destination || livingAt(destination.x, destination.y)) return { success: false, message: '远征移动的落点已失效' };
firedTurns[turalyon.instanceId] = turnNumber;
mover.x = destination.x; mover.y = destination.y;
return { success: true, message: mover.name + '完成圣铸进军，移动至(' + mover.x + ',' + mover.y + ')' };
